/* MODULE gt03 · Bước 3 Đặt giả thuyết · Giả thuyết kiểm chứng được
   10 bài × 7 câu. Thương hiệu được nêu như ví dụ công khai; mọi con số là MINH HOẠ và tự khớp nhau. */
BAI_ADD({ mod:'gt03', lessons:[

/* ------------------------------------------------------------------ 01 */
{ id:'B:gt03-01', skill:'measure', read:'6 phút', t:'"Làm video TikTok sẽ tăng doanh số" đã là giả thuyết chưa?',
  situation:'Một tiệm trà sữa ở Đà Nẵng bán online qua GrabFood, tỉ lệ chuyển đổi trang quán khoảng 2%. Trong cuộc họp, chủ quán nói: "Làm video TikTok sẽ tăng doanh số." Mọi người gật đầu. Ba tuần sau, quán đăng 12 video, doanh số lúc lên lúc xuống, và không ai nói được ý tưởng ban đầu đúng hay sai.',
  concept:{ name:'Khuôn "Nếu… thì… vì…"',
    body:'Một câu dự đoán chỉ thành giả thuyết khi đủ ba phần. <b>Nếu</b>: ta làm gì, cụ thể, với ai. <b>Thì</b>: con số nào thay đổi, bao nhiêu, trong bao lâu. <b>Vì</b>: cơ chế nào khiến điều đó xảy ra — đây là phần hay bị bỏ nhất, nhưng lại là phần cho biết nên làm gì tiếp khi kết quả ra. Thiếu "thì", bạn không biết mình thắng hay thua. Thiếu "vì", có thắng cũng không biết lặp lại thế nào.' },
  example:'Viết lại: "<b>Nếu</b> đăng 3 video/tuần quay cảnh pha trà trong 4 tuần, <b>thì</b> tỉ lệ chuyển đổi trang quán tăng từ 2% lên ít nhất 2,5%, <b>vì</b> khách mới đang ngại gọi thử món lạ và video cho họ thấy ly trà trông ra sao trước khi đặt." Giờ quán biết đo gì (chuyển đổi, không phải lượt xem), ngưỡng nào (tăng 25% tương đối), và nếu sai thì nghi ngờ khâu nào (khách có thật sự ngại món lạ không).',
  takeaway:'Một giả thuyết đủ ba phần: làm gì, số nào đổi bao nhiêu, và vì sao.',
  apply:'Lấy một ý tưởng marketing bạn nghe gần đây. Viết lại thành một câu "Nếu… thì… vì…" và đọc to trong 60 giây.',
  mistakes:['Viết "thì doanh số tăng" mà không nói tăng bao nhiêu, trong bao lâu.','Bỏ phần "vì", nên khi kết quả ra không biết rút ra điều gì.'],
  q:[
  { type:'mcq', stem:'Câu "Làm video TikTok sẽ tăng doanh số" thiếu điều gì quan trọng nhất để kiểm được?',
    options:[{k:'a',t:'Thiếu tên người chịu trách nhiệm quay và dựng video'},{k:'b',t:'Thiếu số đo cụ thể, ngưỡng và lý do vì sao nó sẽ đúng'},
             {k:'c',t:'Thiếu ngân sách chạy quảng cáo để đẩy video lên xu hướng'},{k:'d',t:'Thiếu phân tích đối thủ đang đăng bao nhiêu video mỗi tuần'}],
    answer:'b', why:{a:'Phân công cần cho kế hoạch làm việc, nhưng không giúp biết ý tưởng đúng hay sai.',
      b:'Đúng. Không có số đo và ngưỡng thì mọi kết quả đều "có vẻ đúng"; không có lý do thì không biết học được gì.',
      c:'Ngân sách là đầu vào; câu vẫn không nói kết quả nào sẽ được coi là thành công.',
      d:'Biết đối thủ có ích khi lập kế hoạch, nhưng không biến câu này thành thứ kiểm được.'} },
  { type:'mcq', stem:'Bạn được giao viết lại ý của chủ quán. Bạn chọn câu nào để đưa vào kế hoạch?',
    options:[{k:'a',t:'Nếu làm TikTok đều đặn thì thương hiệu sẽ được nhiều người trẻ biết đến hơn trong thời gian tới'},
             {k:'b',t:'Nếu đăng video mỗi ngày thì lượt xem trung bình sẽ vượt 10.000 lượt mỗi video'},
             {k:'c',t:'Nếu đăng 3 video/tuần trong 4 tuần thì chuyển đổi tăng từ 2% lên 2,5%, vì khách ngại món lạ'},
             {k:'d',t:'TikTok là kênh của người trẻ nên chắc chắn hợp với trà sữa, cần làm ngay tuần này'}],
    answer:'c', why:{a:'"Được biết đến nhiều hơn" và "thời gian tới" không đo được, cũng không có ngưỡng.',
      b:'Có số, nhưng đo lượt xem chứ không đo điều quán cần là đơn hàng; và thiếu phần "vì".',
      c:'Đúng. Có hành động, số đo gắn với doanh số, ngưỡng, thời hạn và cơ chế.',
      d:'Đây là một niềm tin, không phải dự đoán có thể sai; "chắc chắn" chặn luôn việc kiểm.'} },
  { type:'calc', stem:'Chuyển đổi hiện tại là 2%. Giả thuyết đặt ngưỡng: tăng ít nhất 25% so với hiện tại. Ngưỡng chuyển đổi cần đạt là bao nhiêu %?',
    unit:'%', ans:2.5, tol:0.01, wrong:[[27,'NHAM_DIEM_PHAN_TRAM'],[0.5,'NHAM_SO_TUYET_DOI']], errors:['NHAM_DIEM_PHAN_TRAM'],
    steps:['Tăng 25% tương đối nghĩa là nhân với 1,25, không phải cộng 25 điểm.','2% × 1,25 = <b>2,5%</b>.'] },
  { type:'mcq', stem:'Vì sao phần "vì…" đáng viết ra dù không ảnh hưởng tới con số đo?',
    options:[{k:'a',t:'Để sếp thấy kế hoạch có lập luận, dễ được duyệt ngân sách'},{k:'b',t:'Để khi kết quả ra, biết cơ chế nào đúng hay sai và làm gì tiếp'},
             {k:'c',t:'Vì phần "vì" giúp tăng tỉ lệ giả thuyết được chứng minh là đúng sau khi đo'},{k:'d',t:'Vì mẫu kế hoạch của các công ty lớn đều bắt buộc có mục này'}],
    answer:'b', why:{a:'Được duyệt là lợi ích phụ; giá trị chính là học được gì sau khi đo.',
      b:'Đúng. Cùng một con số tăng có thể do nhiều lý do; ghi cơ chế trước giúp bạn biết mình thắng vì đâu.',
      c:'Viết lý do không làm giả thuyết dễ đúng hơn; nó chỉ làm kết quả dễ hiểu hơn.',
      d:'Làm vì mẫu bắt buộc thì phần "vì" sẽ bị viết cho có, mất tác dụng.'} },
  { type:'mcq', stem:'Một shop mỹ phẩm viết: "Nếu giảm phí ship thì khách sẽ thích hơn vì ai cũng ghét phí ship." Nên sửa phần nào trước?',
    options:[{k:'a',t:'Phần "nếu": cần ghi rõ giảm phí ship cho toàn bộ hay chỉ một số tỉnh'},{k:'b',t:'Phần "vì": cần dẫn một nghiên cứu nước ngoài cho thuyết phục hơn'},
             {k:'c',t:'Không cần sửa, vì câu đã có đủ ba phần nếu, thì và vì'},{k:'d',t:'Phần "thì": "thích hơn" không đo được, cần số như tỉ lệ bỏ giỏ'}],
    answer:'d', why:{a:'Làm rõ "nếu" là tốt, nhưng lỗi nặng nhất là kết quả không đo được.',
      b:'Trích dẫn không cứu được một kết quả không có số đo.',
      c:'Có đủ ba chữ không có nghĩa là đủ ba phần; "thích hơn" không phải kết quả kiểm được.',
      d:'Đúng. "Thích hơn" không có số, không có ngưỡng; ví dụ nên là tỉ lệ bỏ giỏ giảm từ 70% xuống 60%.'} },
  { type:'mcq', stem:'Sau 4 tuần, chuyển đổi của quán trà sữa lên 2,6% nhưng khảo sát cho thấy khách mới không hề ngại món lạ. Đọc kết quả thế nào?',
    options:[{k:'a',t:'Giả thuyết đúng hoàn toàn, cứ tăng số video lên gấp đôi'},{k:'b',t:'Con số đạt ngưỡng nhưng lý do có thể sai — cần tìm cơ chế thật'},
             {k:'c',t:'Giả thuyết sai hoàn toàn, nên dừng làm video ngay lập tức'},{k:'d',t:'Kết quả không dùng được vì khảo sát và số đo đang mâu thuẫn nhau rõ rệt'}],
    answer:'b', why:{a:'Nhân đôi video dựa trên một cơ chế đã bị nghi ngờ là đặt cược mù.',
      b:'Đúng. Phần "thì" đạt, phần "vì" chưa; phải biết video giúp ở khâu nào mới làm tiếp đúng hướng.',
      c:'Con số vẫn đạt ngưỡng; dừng lại là bỏ phí một điều đang có tác dụng.',
      d:'Mâu thuẫn chính là thông tin: nó chỉ ra lý do ban đầu sai, không làm kết quả vô dụng.'} },
  { type:'mcq', stem:'Câu nào dưới đây là một giả thuyết đủ ba phần?',
    options:[{k:'a',t:'Nếu đổi ảnh bìa sản phẩm thì trang sẽ đẹp và chuyên nghiệp hơn trước'},{k:'b',t:'Khách hàng Gen Z thích nội dung ngắn, vui, có nhạc bắt tai, bắt trend và có người nổi tiếng xuất hiện'},
             {k:'c',t:'Nếu thêm ảnh thật khách mặc thì tỉ lệ trả hàng giảm từ 12% xuống 9%, vì khách hình dung đúng dáng'},{k:'d',t:'Chạy quảng cáo Facebook sẽ giúp tăng nhận biết thương hiệu'}],
    answer:'c', why:{a:'"Đẹp và chuyên nghiệp" không phải số đo; thiếu cả lý do.',
      b:'Đây là một nhận định về khách, không có hành động, số đo hay ngưỡng.',
      c:'Đúng. Có hành động, số đo có ngưỡng, và cơ chế giải thích vì sao.',
      d:'Thiếu ngưỡng, thời hạn và lý do; "tăng nhận biết" chưa được định lượng.'} }
  ] },

/* ------------------------------------------------------------------ 02 */
{ id:'B:gt03-02', skill:'measure', read:'6 phút', t:'Giả thuyết không thể sai thì có đáng kiểm không?',
  situation:'Một thương hiệu nước mắm ở Phú Quốc chạy chiến dịch "kể chuyện nhà thùng". Trước chiến dịch, trưởng nhóm viết: "Chiến dịch sẽ có tác động tích cực tới thương hiệu." Sau hai tháng, đơn online đứng yên ở khoảng 60 đơn mỗi tháng, nhưng nhóm vẫn báo cáo "thành công" vì bình luận khen nhiều hơn.',
  concept:{ name:'Giả thuyết phải sai được',
    body:'Một giả thuyết tốt phải chỉ ra trước <b>kết quả nào sẽ chứng minh nó sai</b>. "Tác động tích cực tới thương hiệu" không sai được: đơn tăng là tích cực, đơn giảm thì "vẫn tăng nhận biết", bình luận khen cũng tính. Câu nào luôn đúng thì không dạy được gì. Cách thử: hỏi "Con số nào xuất hiện thì tôi sẽ thừa nhận mình sai?" Nếu không trả lời được, câu đó chưa phải giả thuyết.' },
  example:'Nhóm viết lại: "Nếu đăng 8 video kể chuyện nhà thùng trong 2 tháng, thì đơn online từ trang web tăng từ 60 lên ít nhất 80 đơn/tháng trên khoảng 4.000 lượt vào trang, vì khách thành phố tin nước mắm có nguồn gốc rõ hơn." Giờ có vạch sai rõ: dưới 80 đơn là giả thuyết sai. Với 4.000 lượt vào, 80 đơn nghĩa là chuyển đổi cần đạt 2%, so với 1,5% hiện tại.',
  takeaway:'Trước khi chạy, viết ra con số nào sẽ khiến bạn thừa nhận mình sai.',
  apply:'Chọn một mục tiêu chiến dịch bạn từng thấy. Nói trong 60 giây: kết quả cụ thể nào sẽ chứng minh nó thất bại.',
  mistakes:['Chọn số đo sau khi chạy xong, lấy số nào đẹp nhất để báo cáo.','Dùng từ mềm như "tích cực", "cải thiện" để chỗ nào cũng thắng.'],
  q:[
  { type:'mcq', stem:'Vì sao "Chiến dịch sẽ có tác động tích cực tới thương hiệu" là một câu yếu?',
    options:[{k:'a',t:'Vì từ "thương hiệu" quá rộng, nên thay bằng "nhận biết thương hiệu"'},{k:'b',t:'Vì câu quá ngắn, cần viết dài hơn để thể hiện đủ chiến lược'},
             {k:'c',t:'Vì câu hướng tới hình ảnh, trong khi chỉ nên kiểm các chỉ số bán hàng'},{k:'d',t:'Vì kết quả nào cũng có thể gọi là tích cực — câu không thể sai'}],
    answer:'d', why:{a:'Đổi từ vẫn không có ngưỡng; "nhận biết tăng" cũng không sai được nếu không có số.',
      b:'Độ dài không liên quan; một câu ngắn có số và ngưỡng vẫn tốt hơn.',
      c:'Hình ảnh thương hiệu vẫn kiểm được nếu có thước đo và ngưỡng rõ.',
      d:'Đúng. Câu không loại trừ kết quả nào, nên không kiểm được gì.'} },
  { type:'mcq', stem:'Bạn là trưởng nhóm, muốn sửa giả thuyết trước khi chạy. Bạn chọn thêm điều gì?',
    options:[{k:'a',t:'Thêm mục tiêu tổng lượt xem video, vì con số này dễ đạt và dễ báo cáo'},{k:'b',t:'Một vạch rõ: dưới 80 đơn/tháng thì coi như giả thuyết sai'},
             {k:'c',t:'Thêm nhiều chỉ số: lượt xem, lượt thích, bình luận, đơn, để chắc có số tăng'},{k:'d',t:'Thêm câu "nếu chưa đạt thì do thị trường khó khăn chung"'}],
    answer:'b', why:{a:'Chọn số vì dễ đạt là tự bảo đảm thắng — đúng lỗi của câu gốc.',
      b:'Đúng. Vạch sai được ghi trước là thứ biến câu thành giả thuyết.',
      c:'Càng nhiều chỉ số, càng chắc có một chỉ số tăng — bạn sẽ luôn "đúng" mà không học gì.',
      d:'Đây là lối thoát viết sẵn, khiến giả thuyết không bao giờ sai được.'} },
  { type:'calc', stem:'Trang web có khoảng 4.000 lượt vào mỗi tháng. Giả thuyết cần ít nhất 80 đơn/tháng. Tỉ lệ chuyển đổi tối thiểu phải là bao nhiêu %?',
    unit:'%', ans:2, tol:0.01, wrong:[[50,'SAI_MAU_SO'],[0.02,'SAI_TINH_TOAN']], errors:['SAI_MAU_SO'],
    steps:['Chuyển đổi = đơn ÷ lượt vào.','80 ÷ 4.000 = 0,02 = <b>2%</b>.'] },
  { type:'mcq', stem:'Sau chiến dịch, đơn chỉ đạt 64/tháng nhưng bình luận khen tăng gấp ba. Kết luận nào trung thực nhất?',
    options:[{k:'a',t:'Chiến dịch thành công vì khách yêu thương hiệu hơn rõ rệt'},{k:'b',t:'Chưa kết luận được, cần chạy thêm vài tháng cho số đơn bắt kịp'},
             {k:'c',t:'Giả thuyết về đơn hàng sai; nội dung được thích nhưng chưa khiến khách mua'},{k:'d',t:'Số đơn không quan trọng bằng bình luận khen ở giai đoạn đầu của một chiến dịch thương hiệu'}],
    answer:'c', why:{a:'Đổi thước đo sau khi thấy kết quả là cách né thừa nhận sai.',
      b:'Kéo dài thời hạn sau khi trượt ngưỡng cũng là một cách dời vạch sai.',
      c:'Đúng. Ngưỡng 80 không đạt; điều học được là nội dung tạo cảm tình nhưng chưa chạm tới quyết định mua.',
      d:'Nếu bình luận quan trọng hơn thì phải ghi như vậy từ trước, không đổi sau khi có số.'} },
  { type:'mcq', stem:'Câu nào sau đây sai được?',
    options:[{k:'a',t:'Nếu gửi mã giảm 15% cho khách 90 ngày chưa mua lại thì ít nhất 8% quay lại trong 2 tuần'},{k:'b',t:'Livestream sẽ giúp thương hiệu gần gũi hơn với khách hàng trẻ'},
             {k:'c',t:'Bao bì mới có thể sẽ được một số khách hàng yêu thích hơn'},{k:'d',t:'Chạy KOL có lẽ sẽ giúp ích cho doanh số của thương hiệu tuỳ theo từng giai đoạn và từng mùa bán hàng'}],
    answer:'a', why:{a:'Đúng. Có con số và thời hạn; dưới 8% là sai rõ ràng.',
      b:'"Gần gũi hơn" không có thước đo nên kết quả nào cũng khớp.',
      c:'"Có thể", "một số" khiến câu đúng trong mọi trường hợp.',
      d:'"Có lẽ" và "tuỳ giai đoạn" là hai lối thoát; câu không thể sai.'} },
  { type:'mcq', stem:'Một đồng nghiệp nói: "Viết ngưỡng rõ quá thì dễ bị sếp đánh giá là thất bại." Cách phản hồi tốt nhất?',
    options:[{k:'a',t:'Đồng ý, nên đặt ngưỡng thấp hẳn để chắc chắn vượt qua được'},{k:'b',t:'Đồng ý, nên chỉ báo cáo con số sau khi đã có kết quả tốt'},
             {k:'c',t:'Không đồng ý, vì sếp nào cũng luôn thích con số mục tiêu thật cao dù cuối cùng có đạt hay không'},{k:'d',t:'Giả thuyết sai mà rõ ràng vẫn cho bài học; mơ hồ thì tốn tiền mà chẳng học gì'}],
    answer:'d', why:{a:'Ngưỡng thấp để chắc thắng biến việc kiểm thành màn trình diễn.',
      b:'Báo cáo có chọn lọc làm cả nhóm mất khả năng biết điều gì thật sự hiệu quả.',
      c:'Lý do đúng không nằm ở sở thích của sếp mà ở giá trị của việc học.',
      d:'Đúng. Một kết quả sai rõ giúp tránh lặp lại sai lầm; kết quả mơ hồ thì không giúp gì.'} },
  { type:'mcq', stem:'Nhóm đặt ngưỡng 80 đơn, kết quả 78. Trưởng nhóm muốn nói "gần đạt, coi như đúng". Nên làm gì?',
    options:[{k:'a',t:'Ghi nhận không đạt ngưỡng, xem xu hướng theo tuần để quyết định có kiểm lại không'},{k:'b',t:'Coi là đạt vì 78 và 80 chênh lệch rất nhỏ, không đáng kể'},
             {k:'c',t:'Giữ kết luận "đúng" và hạ ngưỡng xuống 75 cho kỳ sau để lần tới chắc chắn sẽ đạt được'},{k:'d',t:'Bỏ kết quả này vì số đơn quá ít nên không có ý nghĩa gì'}],
    answer:'a', why:{a:'Đúng. Giữ nguyên vạch đã đặt; nếu thấy xu hướng tăng dần thì có lý do kiểm lần hai.',
      b:'Nới vạch sau khi có số là tự làm mất tác dụng của việc đặt ngưỡng.',
      c:'Hạ ngưỡng vì sợ trượt là đổi mục tiêu cho vừa kết quả.',
      d:'Số ít làm kết quả kém chắc chắn, nhưng vẫn là thông tin; bỏ đi là phí.'} }
  ] },

/* ------------------------------------------------------------------ 03 */
{ id:'B:gt03-03', skill:'measure', read:'7 phút', t:'Số nào sẽ chứng minh bạn đúng — và bao nhiêu thì đủ?',
  situation:'Một chuỗi phòng gym ở Hà Nội đang có chi phí để có một hội viên mới (CAC) khoảng 150.000 đồng qua quảng cáo Facebook. Nhóm marketing muốn thử kênh Zalo OA với giả thuyết "Zalo rẻ hơn". Sau 3 tuần tiêu 6 triệu đồng và có 45 hội viên mới, nhóm cãi nhau: có người nói rẻ hơn, có người nói không.',
  concept:{ name:'Chỉ số quyết định và ngưỡng hành động',
    body:'Trước khi chạy, chọn <b>một chỉ số quyết định</b> gắn trực tiếp với điều bạn cần biết, và <b>một ngưỡng hành động</b>: vượt ngưỡng thì làm gì, dưới ngưỡng thì làm gì. Ngưỡng không lấy ngẫu nhiên mà suy từ kinh doanh: đủ tốt để đáng chuyển tiền sang không, sau khi tính công sức thêm? Có thể thêm chỉ số phụ để hiểu vì sao, nhưng chỉ số phụ không được dùng để lật kết quả.' },
  example:'Giả thuyết viết lại: "Nếu chạy Zalo OA 3 tuần với 6 triệu đồng, thì CAC ≤ 120.000 đồng, vì khách quanh khu đã theo dõi OA của phòng gym." Ngưỡng 120.000 chọn vì thấp hơn Facebook 20% — đủ bù công quản lý thêm một kênh. Kết quả: 6.000.000 ÷ 45 ≈ 133.000 đồng. Rẻ hơn Facebook, nhưng chưa qua ngưỡng hành động → chưa chuyển ngân sách, chỉ giữ ở mức thử.',
  takeaway:'Chọn một số quyết định và một ngưỡng hành động trước, để kết quả tự nói phải làm gì.',
  apply:'Với một kênh bạn muốn thử, nói trong 60 giây: chỉ số quyết định là gì, ngưỡng bao nhiêu và vì sao là con số đó.',
  mistakes:['Chỉ viết "rẻ hơn" mà không nói rẻ hơn bao nhiêu thì mới đáng chuyển tiền.','Dùng chỉ số phụ đẹp để lật một kết quả chính không đạt.'],
  q:[
  { type:'mcq', stem:'Nhóm gym cãi nhau vì "rẻ hơn" hay "không rẻ hơn". Gốc của cuộc cãi nằm ở đâu?',
    options:[{k:'a',t:'Chưa thống nhất trước chỉ số và ngưỡng nào thì gọi là rẻ hơn'},{k:'b',t:'Ba tuần là quá ngắn, cần ít nhất ba tháng mới đủ dữ liệu'},
             {k:'c',t:'Zalo và Facebook có cách tính chi phí khác nhau nên không thể so sánh'},{k:'d',t:'45 hội viên là con số quá nhỏ để rút ra bất kỳ kết luận nào'}],
    answer:'a', why:{a:'Đúng. Không có ngưỡng đặt trước thì mỗi người tự chọn vạch của mình.',
      b:'Thời gian dài hơn vẫn sẽ gây cãi nếu không có ngưỡng.',
      c:'CAC quy về cùng một đơn vị tiền trên hội viên, nên so được.',
      d:'Số ít làm kết luận kém chắc, nhưng không phải nguyên nhân của cuộc cãi.'} },
  { type:'mcq', stem:'Bạn phải chọn chỉ số quyết định cho thử nghiệm Zalo OA. Bạn chọn chỉ số nào?',
    options:[{k:'a',t:'Số người quan tâm OA mới trong ba tuần chạy thử'},{k:'b',t:'Tỉ lệ mở tin nhắn trên Zalo so với tỉ lệ mở email trước đây'},
             {k:'c',t:'Chi phí trên một hội viên mới đăng ký gói tập'},{k:'d',t:'Số lượt nhấn vào đường dẫn đặt lịch tập thử miễn phí'}],
    answer:'c', why:{a:'Người quan tâm OA chưa phải hội viên; có thể nhiều mà không ai mua gói.',
      b:'Tỉ lệ mở giúp hiểu nội dung, nhưng câu hỏi là kênh có rẻ hơn để có hội viên không.',
      c:'Đúng. Giả thuyết là "rẻ hơn", nên chỉ số phải là chi phí cho kết quả kinh doanh.',
      d:'Lượt nhấn là bước giữa; nhấn nhiều mà không đăng ký thì kênh vẫn đắt.'} },
  { type:'calc', stem:'Zalo OA tiêu 6.000.000 đồng, có 45 hội viên mới. CAC là bao nhiêu nghìn đồng (làm tròn 1 chữ số thập phân)?',
    unit:'nghìn đồng', ans:133.3, tol:0.2, wrong:[[7.5,'SAI_MAU_SO'],[150,'SAI_TINH_TOAN']], errors:['SAI_MAU_SO'],
    steps:['CAC = chi phí ÷ số khách mới.','6.000.000 ÷ 45 ≈ 133.333 đồng ≈ <b>133,3 nghìn đồng</b>.'] },
  { type:'mcq', stem:'Vì sao ngưỡng là 120.000 đồng chứ không phải "cứ thấp hơn 150.000"?',
    options:[{k:'a',t:'Vì 120.000 là số tròn, dễ nhớ, dễ trình bày trong báo cáo gửi ban giám đốc'},{k:'b',t:'Vì muốn đặt mục tiêu khó để đội ngũ phải cố gắng nhiều hơn'},
             {k:'c',t:'Vì Zalo OA thường rẻ hơn Facebook đúng 20% ở mọi ngành'},{k:'d',t:'Vì thêm kênh tốn công; chỉ rẻ hơn rõ rệt mới đáng chuyển tiền sang'}],
    answer:'d', why:{a:'Số tròn tiện, nhưng ngưỡng phải có lý do kinh doanh.',
      b:'Ngưỡng dùng để quyết định, không phải để tạo áp lực.',
      c:'Không có quy luật chênh lệch cố định như vậy; ngưỡng suy từ bài toán của chính bạn.',
      d:'Đúng. Ngưỡng hành động tính cả chi phí ẩn của việc quản lý thêm kênh.'} },
  { type:'mcq', stem:'CAC Zalo ra 133.000 đồng, nhưng tỉ lệ hội viên Zalo gia hạn tháng thứ hai cao hơn. Làm gì với thông tin này?',
    options:[{k:'a',t:'Lật kết quả: coi Zalo là thắng và chuyển ngay phần lớn ngân sách'},{k:'b',t:'Ghi nhận chưa đạt ngưỡng; đặt giả thuyết mới về giá trị hội viên'},
             {k:'c',t:'Bỏ qua dữ liệu gia hạn vì không nằm trong giả thuyết ban đầu'},{k:'d',t:'Tính lại CAC chỉ trên hội viên đã gia hạn cho ra số đẹp hơn'}],
    answer:'b', why:{a:'Dùng chỉ số phụ để lật kết quả chính là né vạch đã đặt.',
      b:'Đúng. Tín hiệu gia hạn đáng giá, nhưng nó là giả thuyết tiếp theo cần kiểm riêng.',
      c:'Bỏ qua là phí thông tin; chỉ là không dùng nó để đổi kết luận cũ.',
      d:'Đổi mẫu số để số đẹp hơn là tự đánh lừa mình.'} },
  { type:'mcq', stem:'Một quán cà phê thử bán combo sáng, ngưỡng đặt trước: giá trị đơn trung bình từ 45.000 lên 52.000 đồng. Kết quả 55.000 nhưng số đơn buổi sáng giảm 15%. Kết luận nào đúng?',
    options:[{k:'a',t:'Thắng rõ, vì đơn trung bình vượt ngưỡng đã đặt'},{k:'b',t:'Thua rõ, vì số đơn giảm là tín hiệu xấu nhất có thể'},
             {k:'c',t:'Cần xem doanh thu sáng; lẽ ra phải đặt ngưỡng trên chỉ số tổng'},{k:'d',t:'Không kết luận được gì vì hai chỉ số đang đi ngược chiều nhau'}],
    answer:'c', why:{a:'Đơn to hơn mà ít đơn hơn thì doanh thu có thể giảm; chỉ số chọn chưa đủ gắn với mục tiêu.',
      b:'Giảm số đơn có thể được bù bằng đơn to hơn; chưa thể nói thua.',
      c:'Đúng. 55 × 0,85 ≈ 46,8 so với 45: doanh thu vẫn nhích, nhưng bài học là chọn chỉ số quyết định sát mục tiêu hơn.',
      d:'Hai chỉ số ngược chiều thì gộp lại thành doanh thu là kết luận được.'} },
  { type:'mcq', stem:'Điều nào nên ghi ra TRƯỚC khi chạy một thử nghiệm kênh mới?',
    options:[{k:'a',t:'Tên kênh, ngân sách và khung thời gian chạy'},{k:'b',t:'Danh sách mọi chỉ số có thể theo dõi được trên trang quản lý'},
             {k:'c',t:'Dự kiến bài đăng tổng kết thành công gửi cho ban giám đốc'},{k:'d',t:'Chỉ số quyết định, ngưỡng, và việc sẽ làm ở mỗi phía ngưỡng'}],
    answer:'d', why:{a:'Cần, nhưng chưa đủ để kết quả tự nói phải làm gì.',
      b:'Nhiều chỉ số không có thứ bậc là mầm của cuộc cãi sau này.',
      c:'Viết trước lời báo cáo thành công là thiên kiến ngay từ đầu.',
      d:'Đúng. Ghi hành động cho cả hai phía ngưỡng biến kết quả thành quyết định.'} }
  ] },

/* ------------------------------------------------------------------ 04 */
{ id:'B:gt03-04', skill:'insight', read:'6 phút', t:'Vấn đề nằm ở khách, ở kênh hay ở thông điệp?',
  situation:'Một thương hiệu sữa hạt ở TP.HCM chạy quảng cáo với câu "Ít đường, tốt cho tim mạch" nhắm dân văn phòng 25–35 tuổi. Tỉ lệ nhấp quảng cáo (CTR) chỉ 1,2%, thấp hơn các chiến dịch cũ. Nhóm đưa ra ba ý: đổi tệp khách, đổi sang TikTok, hay đổi câu quảng cáo — và muốn làm cả ba cùng lúc.',
  concept:{ name:'Ba loại giả thuyết: khách – kênh – thông điệp',
    body:'Khi kết quả kém, nguyên nhân thường thuộc một trong ba nhóm. <b>Khách</b>: nói với sai người, họ không có nhu cầu. <b>Kênh</b>: đúng người nhưng gặp họ sai chỗ, sai lúc. <b>Thông điệp</b>: đúng người, đúng chỗ nhưng nói điều họ không quan tâm. Mỗi loại cần kiểm cách khác nhau và giữ hai yếu tố kia cố định. Đổi cả ba cùng lúc thì kết quả tốt hay xấu cũng không biết do đâu.' },
  example:'Nhóm hỏi: điều gì rẻ và nhanh nhất để tách ra? Họ giữ nguyên tệp và kênh, chỉ đổi thông điệp: "Ít đường, tốt cho tim mạch" với "Uống sáng no tới trưa, không buồn ngủ". Giả thuyết: "Nếu nói về cảm giác trong ngày thay vì sức khoẻ dài hạn, thì CTR tăng từ 1,2% lên ít nhất 1,6%, vì dân văn phòng 25–35 chưa lo tim mạch." Kết quả mẫu mới đạt 1,8% — tăng 50% tương đối.',
  takeaway:'Đổi một thứ mỗi lần: khách, kênh hoặc thông điệp — để biết cái gì tạo ra kết quả.',
  apply:'Nhìn một quảng cáo bạn thấy hôm nay. Trong 60 giây, đặt một giả thuyết vì sao nó có thể kém, rồi nói nó thuộc loại khách, kênh hay thông điệp.',
  mistakes:['Đổi cả tệp, kênh và câu chữ cùng lúc rồi không biết cái gì có tác dụng.','Mặc định lỗi ở kênh vì đổi kênh trông như một hành động lớn.'],
  q:[
  { type:'mcq', stem:'CTR 1,2% thấp. Nếu vấn đề nằm ở THÔNG ĐIỆP, dấu hiệu nào khớp nhất?',
    options:[{k:'a',t:'Quảng cáo ít được hiển thị vì ngân sách hết sớm trong ngày'},{k:'b',t:'Người xem đúng tệp nhưng lướt qua; khảo sát nói "chưa lo tim mạch"'},
             {k:'c',t:'Phần lớn người xem ở ngoài độ tuổi và khu vực đã nhắm tới'},{k:'d',t:'Người đúng tệp hầu như không dùng mạng xã hội vào giờ quảng cáo chạy'}],
    answer:'b', why:{a:'Hiển thị ít là vấn đề phân phối, không nói gì về câu chữ.',
      b:'Đúng. Đúng người, đúng chỗ, nhưng lý do đưa ra không chạm tới mối quan tâm của họ.',
      c:'Đây là dấu hiệu của vấn đề về khách/tệp nhắm.',
      d:'Đây là dấu hiệu của vấn đề về kênh hoặc thời điểm.'} },
  { type:'mcq', stem:'Nhóm muốn đổi cả tệp, kênh và câu chữ cùng lúc để "cứu" chiến dịch. Bạn đề xuất gì?',
    options:[{k:'a',t:'Làm cả ba cùng lúc để tiết kiệm thời gian, rồi xem tổng kết quả'},{k:'b',t:'Chuyển hẳn sang TikTok trước, vì kênh mới sẽ có nhiều khách mới'},
             {k:'c',t:'Đổi tệp sang 18–24 trước vì người trẻ nhấp quảng cáo nhiều hơn'},{k:'d',t:'Giữ tệp và kênh, thử đổi thông điệp trước vì rẻ và nhanh nhất'}],
    answer:'d', why:{a:'Kết quả tăng hay giảm đều không biết do yếu tố nào.',
      b:'Đổi kênh tốn nhất và lại chưa có bằng chứng lỗi ở kênh.',
      c:'Đổi tệp có thể làm CTR đẹp nhưng sai người mua thật.',
      d:'Đúng. Tách một yếu tố, bắt đầu từ cái rẻ nhất, để biết chắc cái gì tác động.'} },
  { type:'calc', stem:'CTR từ 1,2% lên 1,8%. Mức tăng tương đối là bao nhiêu %?',
    unit:'%', ans:50, tol:0.1, wrong:[[0.6,'NHAM_DIEM_PHAN_TRAM'],[33.3,'SAI_MAU_SO']], errors:['NHAM_DIEM_PHAN_TRAM'],
    steps:['Tăng tuyệt đối: 1,8 − 1,2 = 0,6 điểm phần trăm.','Tăng tương đối: 0,6 ÷ 1,2 = 0,5 = <b>50%</b>.'] },
  { type:'mcq', stem:'Một app học tiếng Anh có nhiều lượt tải từ quảng cáo nhưng người dùng hầu hết trên 45 tuổi, không phải sinh viên như dự định. Đây là giả thuyết loại nào cần xem lại?',
    options:[{k:'a',t:'Về khách: quảng cáo đang tới đúng người có nhu cầu hay không'},{k:'b',t:'Về thông điệp: câu chữ chưa đủ hấp dẫn nên cần viết lại'},
             {k:'c',t:'Về kênh: cần chuyển toàn bộ ngân sách sang TikTok ngay'},{k:'d',t:'Về sản phẩm: app cần thêm tính năng mới dành riêng cho người lớn tuổi'}],
    answer:'a', why:{a:'Đúng. Có lượt tải nhưng sai người — cần kiểm lại tệp nhắm và ai thật sự có nhu cầu.',
      b:'Thông điệp đang hút được người; vấn đề là hút sai người.',
      c:'Kênh có thể liên quan, nhưng đổi kênh trước khi hiểu vấn đề tệp là đoán mò.',
      d:'Sản phẩm có thể là cơ hội, nhưng câu hỏi hiện tại là quảng cáo đang nhắm ai.'} },
  { type:'mcq', stem:'Cách nào kiểm được giả thuyết KÊNH mà không lẫn thông điệp?',
    options:[{k:'a',t:'Chạy câu mới trên TikTok và so với câu cũ trên Facebook'},{k:'b',t:'Chạy cùng một câu, cùng tệp tuổi trên hai kênh rồi so chi phí/đơn'},
             {k:'c',t:'Hỏi khách hàng hiện tại xem họ thích kênh nào hơn qua một bảng khảo sát'},{k:'d',t:'Chạy trên kênh mới với tệp rộng hơn cho nhanh có dữ liệu'}],
    answer:'b', why:{a:'Đổi cả kênh và câu chữ nên không tách được tác động.',
      b:'Đúng. Giữ thông điệp và tệp cố định, chỉ kênh thay đổi.',
      c:'Lời nói về sở thích kênh không thay được số đo hành vi.',
      d:'Đổi tệp cùng lúc lại trộn thêm một yếu tố.'} },
  { type:'mcq', stem:'Một thương hiệu nước tăng lực chạy quảng cáo vào 7 giờ sáng trên YouTube, ít người xem hết. Khách quen nói họ uống vào chiều tối khi tăng ca. Giả thuyết nên thuộc loại nào?',
    options:[{k:'a',t:'Về thông điệp: câu quảng cáo chưa nói rõ công dụng tỉnh táo'},{k:'b',t:'Về khách: tệp dân văn phòng không phải khách của nước tăng lực'},
             {k:'c',t:'Về kênh/thời điểm: gặp đúng người nhưng sai lúc họ cần'},{k:'d',t:'Về giá: sản phẩm đắt hơn đối thủ nên khách không chú ý'}],
    answer:'c', why:{a:'Chưa có dấu hiệu câu chữ sai; dữ kiện nói về thời điểm dùng.',
      b:'Khách quen đúng là dân tăng ca, nên tệp không phải vấn đề chính.',
      c:'Đúng. Dữ kiện chỉ ra thời điểm tiếp cận lệch với lúc có nhu cầu.',
      d:'Giá không liên quan tới việc ít người xem hết quảng cáo buổi sáng.'} },
  { type:'mcq', stem:'Vì sao nên thử giả thuyết thông điệp trước giả thuyết kênh trong nhiều trường hợp?',
    options:[{k:'a',t:'Vì thông điệp luôn là nguyên nhân phổ biến nhất khi quảng cáo kém'},{k:'b',t:'Vì kênh không bao giờ là vấn đề nếu đã chạy trên Facebook'},
             {k:'c',t:'Vì sếp thường dễ duyệt việc đổi câu chữ hơn đổi kênh'},{k:'d',t:'Vì đổi câu chữ thường rẻ và nhanh hơn dựng hẳn một kênh mới'}],
    answer:'d', why:{a:'Không có quy luật "luôn luôn"; thứ tự nên theo chi phí kiểm và bằng chứng.',
      b:'Kênh hoàn toàn có thể sai, kể cả Facebook.',
      c:'Dễ duyệt là lợi ích phụ; lý do chính là chi phí kiểm thấp.',
      d:'Đúng. Khi bằng chứng ngang nhau, bắt đầu từ giả thuyết rẻ nhất để kiểm.'} }
  ] },

/* ------------------------------------------------------------------ 05 */
{ id:'B:gt03-05', skill:'insight', read:'7 phút', t:'Doanh thu giảm 20% — nên tin giả thuyết đầu tiên nghĩ ra không?',
  situation:'Một shop giày trên Shopee thấy doanh thu tháng này giảm khoảng 20%. Chủ shop lập tức kết luận: "Đối thủ mới giảm giá, khách bỏ sang bên đó." Anh định giảm giá 10% cho toàn bộ sản phẩm ngay tuần sau. Nhân viên phân tích có dữ liệu lượt vào shop, tỉ lệ chuyển đổi và giá trị đơn trung bình nhưng chưa ai nhìn.',
  concept:{ name:'Nhiều giả thuyết cạnh tranh',
    body:'Với một hiện tượng, hãy viết ra <b>ít nhất ba giả thuyết khác nhau</b> trước khi tin cái nào. Sau đó hỏi: nếu giả thuyết này đúng, dữ liệu sẽ trông thế nào — và dữ liệu nào sẽ phân biệt nó với các giả thuyết khác? Đối thủ giảm giá, thuật toán sàn giảm hiển thị, hay mẫu mới kém hấp dẫn đều làm doanh thu giảm, nhưng để lại dấu vết khác nhau. Giả thuyết đầu tiên thường là cái dễ nghĩ nhất, chưa chắc là cái đúng.' },
  example:'Ba giả thuyết và dấu vết dự kiến: (1) đối thủ giảm giá → lượt vào gần như giữ, chuyển đổi giảm mạnh; (2) sàn giảm hiển thị → lượt vào giảm, chuyển đổi giữ; (3) mẫu mới kém → chuyển đổi giảm ở đúng mẫu mới. Dữ liệu: lượt vào 10.000 → 9.500, chuyển đổi 3% → 2,5%, giá trị đơn 300.000 đồng không đổi. Doanh thu 90 triệu → 71,25 triệu. Chuyển đổi giảm nhiều hơn lượt vào, nên (1) hoặc (3) đáng xem — tách tiếp theo từng mẫu giày.',
  takeaway:'Viết ba giả thuyết và dấu vết của từng cái, rồi để dữ liệu loại bớt.',
  apply:'Nghĩ về một lần doanh số bạn từng thấy giảm. Trong 60 giây, nói ba nguyên nhân khác nhau và mỗi nguyên nhân sẽ để lại dấu vết gì.',
  mistakes:['Hành động ngay theo giả thuyết đầu tiên, nhất là khi nó đổ cho đối thủ.','Viết nhiều giả thuyết nhưng không nói dữ liệu nào phân biệt chúng.'],
  q:[
  { type:'mcq', stem:'Chủ shop định giảm giá 10% toàn bộ ngay. Rủi ro lớn nhất là gì?',
    options:[{k:'a',t:'Khách quen sẽ phàn nàn vì họ đã mua với giá cao hơn trước đó'},{k:'b',t:'Sàn Shopee sẽ phạt shop vì thay đổi giá quá thường xuyên'},
             {k:'c',t:'Nếu nguyên nhân thật không phải giá, shop mất biên lãi mà doanh thu không về'},{k:'d',t:'Đối thủ sẽ giảm giá sâu thêm nữa và kéo cả ngành giày vào một cuộc chiến giá kéo dài'}],
    answer:'c', why:{a:'Có thể xảy ra nhưng là rủi ro nhỏ so với việc chữa sai bệnh.',
      b:'Không phải vấn đề chính của quyết định này.',
      c:'Đúng. Hành động theo một giả thuyết chưa kiểm có thể tốn tiền mà không chạm nguyên nhân.',
      d:'Rủi ro có thật, nhưng chỉ đáng lo nếu giá đúng là nguyên nhân.'} },
  { type:'mcq', stem:'Bạn là nhân viên phân tích, có 30 phút trước buổi họp. Bạn chọn làm gì?',
    options:[{k:'a',t:'Chuẩn bị bảng so giá từng mẫu với đối thủ để ủng hộ quyết định giảm giá của chủ shop'},{k:'b',t:'Viết ba giả thuyết, dấu vết mỗi cái, rồi đối chiếu với lượt vào và chuyển đổi'},
             {k:'c',t:'Đề xuất tăng ngân sách quảng cáo để kéo lại lượt vào bị mất'},{k:'d',t:'Đề xuất chờ thêm một tháng xem doanh thu có tự hồi phục không'}],
    answer:'b', why:{a:'Chỉ đi tìm dữ liệu ủng hộ một giả thuyết là thiên kiến xác nhận.',
      b:'Đúng. Ba mươi phút đủ để tách lượt vào và chuyển đổi, loại bớt giả thuyết.',
      c:'Đây lại là một giải pháp cho một giả thuyết chưa kiểm (sàn giảm hiển thị).',
      d:'Chờ mà không phân tích là bỏ phí dữ liệu đang có.'} },
  { type:'calc', stem:'Lượt vào 9.500, chuyển đổi 2,5%, giá trị đơn trung bình 300.000 đồng. Doanh thu tháng này là bao nhiêu triệu đồng?',
    unit:'triệu đồng', ans:71.25, tol:0.05, wrong:[[712.5,'NHAM_DIEM_PHAN_TRAM'],[90,'SAI_TINH_TOAN']], errors:['QUEN_TI_LE_CHUYEN_DOI'],
    steps:['Số đơn = 9.500 × 2,5% = 237,5 đơn.','Doanh thu = 237,5 × 300.000 = 71.250.000 đồng = <b>71,25 triệu</b>.'] },
  { type:'mcq', stem:'Dữ liệu: lượt vào giảm 5%, chuyển đổi giảm từ 3% xuống 2,5%. Giả thuyết nào bị yếu đi nhiều nhất?',
    options:[{k:'a',t:'Đối thủ giảm giá khiến khách vào xem rồi mua bên khác'},{k:'b',t:'Mẫu giày mới kém hấp dẫn nên khách xem rồi không mua'},
             {k:'c',t:'Giá của shop đang cao hơn mặt bằng chung của ngành giày trên sàn'},{k:'d',t:'Sàn giảm hiển thị là nguyên nhân chính khiến doanh thu tụt'}],
    answer:'d', why:{a:'Giả thuyết này dự đoán chuyển đổi giảm — khớp với dữ liệu.',
      b:'Cũng dự đoán chuyển đổi giảm — vẫn còn sống.',
      c:'Giá cao cũng làm chuyển đổi giảm — vẫn cần xem.',
      d:'Đúng. Nếu sàn giảm hiển thị là chính, lượt vào phải giảm mạnh; ở đây chỉ giảm 5%.'} },
  { type:'mcq', stem:'Để phân biệt "đối thủ giảm giá" với "mẫu mới kém", dữ liệu nào hữu ích nhất?',
    options:[{k:'a',t:'Chuyển đổi tách theo từng mẫu: mẫu cũ và mẫu mới'},{k:'b',t:'Tổng lượt theo dõi shop trong ba tháng gần nhất'},
             {k:'c',t:'Số bình luận và đánh giá sao trung bình của shop'},{k:'d',t:'Chi phí quảng cáo tìm kiếm trên sàn tháng này so với tháng trước'}],
    answer:'a', why:{a:'Đúng. Nếu chỉ mẫu mới giảm → nghiêng về (3); nếu mẫu nào cũng giảm → nghiêng về giá đối thủ.',
      b:'Lượt theo dõi không phân biệt được hai giả thuyết này.',
      c:'Đánh giá chung không tách theo mẫu.',
      d:'Chi phí quảng cáo liên quan đến lượt vào, không phải điều đang cần tách.'} },
  { type:'mcq', stem:'Một quán phở thấy lượng khách buổi trưa giảm. Ba giả thuyết nào là một bộ cạnh tranh tốt?',
    options:[{k:'a',t:'Phở chưa ngon; phở hơi nhạt so với trước; nước dùng thiếu vị ngọt từ xương'},{k:'b',t:'Giá cao; công trình đào đường trước quán; văn phòng gần đó chuyển đi'},
             {k:'c',t:'Khách chán phở; khách không thích phở; khách thích món khác'},{k:'d',t:'Cần quảng cáo; cần giảm giá; cần đổi thực đơn buổi trưa'}],
    answer:'b', why:{a:'Ba câu thực chất là một giả thuyết về vị, không cạnh tranh nhau.',
      b:'Đúng. Ba nguyên nhân khác hẳn nhau và để lại dấu vết khác nhau.',
      c:'Ba cách nói cùng một ý.',
      d:'Đây là ba giải pháp, không phải ba giả thuyết về nguyên nhân.'} },
  { type:'mcq', stem:'Vì sao giả thuyết "đối thủ giảm giá" thường xuất hiện đầu tiên?',
    options:[{k:'a',t:'Vì đó luôn là nguyên nhân phổ biến nhất trên sàn thương mại điện tử'},{k:'b',t:'Vì dữ liệu giá đối thủ là loại dữ liệu dễ lấy và đáng tin nhất'},
             {k:'c',t:'Vì nó dễ nhìn thấy và đổ lỗi ra bên ngoài, không phải nhìn vào mình'},{k:'d',t:'Vì các chuyên gia đều khuyên kiểm giá đối thủ trước tiên'}],
    answer:'c', why:{a:'Không có bằng chứng đó là nguyên nhân "luôn luôn" phổ biến nhất.',
      b:'Dễ lấy không có nghĩa là đúng nguyên nhân.',
      c:'Đúng. Nguyên nhân bên ngoài dễ thấy và dễ chấp nhận hơn lỗi của chính mình.',
      d:'Không có lời khuyên chung như vậy; thứ tự kiểm theo dữ liệu.'} }
  ] },

/* ------------------------------------------------------------------ 06 */
{ id:'B:gt03-06', skill:'insight', read:'6 phút', t:'Chỉ đọc bình luận khen thì có kiểm được giả thuyết không?',
  situation:'Một thương hiệu bánh tráng trộn đóng gói đổi sang bao bì giấy kraft, giả thuyết là "khách mua vì bao bì thân thiện môi trường". Trưởng nhóm lưu lại 15 bình luận khen bao bì và coi đó là bằng chứng. Khảo sát 240 người mua lại cho thấy chỉ 18 người nhắc tới bao bì khi được hỏi lý do mua.',
  concept:{ name:'Thiên kiến xác nhận',
    body:'Khi đã tin một điều, ta có xu hướng <b>tìm, nhớ và tin</b> dữ liệu ủng hộ nó, và bỏ qua dữ liệu ngược lại. Bình luận khen tự đến với bạn; người không quan tâm bao bì thì không bình luận. Cách chống: trước khi nhìn dữ liệu, viết ra "nếu tôi sai, tôi sẽ thấy gì", rồi chủ động đi tìm đúng thứ đó. Dữ liệu từ toàn bộ khách, không chỉ người lên tiếng, mới cho biết một điều phổ biến tới đâu.' },
  example:'15 bình luận khen là thật, nhưng chúng đến từ những người tự chọn lên tiếng. Khảo sát 240 người mua lại: 18 người nhắc bao bì, tức 7,5%. Phần lớn nói về vị cay và giá. Kết luận trung thực: bao bì là lý do của một nhóm nhỏ, không phải động lực chính. Giả thuyết cần sửa: bao bì có thể giúp ở khâu được chú ý trên kệ, không phải ở khâu mua lại.',
  takeaway:'Trước khi nhìn dữ liệu, viết ra mình sẽ thấy gì nếu mình sai — rồi đi tìm đúng thứ đó.',
  apply:'Nghĩ về một niềm tin bạn có về khách hàng. Nói trong 60 giây: bằng chứng nào sẽ khiến bạn đổi ý, và tìm ở đâu.',
  mistakes:['Gom bình luận khen làm bằng chứng mà quên người im lặng.','Chỉ đặt câu hỏi khảo sát theo kiểu gợi ý câu trả lời mình mong.'],
  q:[
  { type:'mcq', stem:'15 bình luận khen bao bì có đủ để kết luận "khách mua vì bao bì" không?',
    options:[{k:'a',t:'Có, vì 15 người độc lập cùng khen một điều là bằng chứng khá mạnh'},{k:'b',t:'Có, vì bình luận là phản hồi tự nguyện nên thật lòng hơn khảo sát'},
             {k:'c',t:'Chưa, vì cần ít nhất 100 bình luận khen mới đủ độ tin cậy'},{k:'d',t:'Chưa, vì người bình luận tự chọn lên tiếng; không đại diện cho người mua'}],
    answer:'d', why:{a:'15 người thật nhưng không cho biết bao nhiêu người mua vì lý do khác.',
      b:'Thật lòng không có nghĩa là đại diện; người không quan tâm bao bì thì không bình luận.',
      c:'Số lượng bình luận khen nhiều hơn vẫn là mẫu tự chọn.',
      d:'Đúng. Mẫu tự chọn phóng to ý kiến của nhóm quan tâm nhất.'} },
  { type:'mcq', stem:'Bạn muốn kiểm giả thuyết bao bì một cách công bằng. Bạn chọn cách nào?',
    options:[{k:'a',t:'Hỏi khách "Bạn có thích bao bì thân thiện môi trường mới không?"'},{k:'b',t:'Đếm thêm bình luận khen trên TikTok để có nhiều bằng chứng hơn'},
             {k:'c',t:'Hỏi câu mở "Vì sao bạn mua?" với mẫu người mua, rồi đếm lý do'},{k:'d',t:'Nhờ KOL đánh giá bao bì và đếm lượt thích của bài đăng đó'}],
    answer:'c', why:{a:'Câu hỏi gợi sẵn đáp án, ai cũng dễ nói "có".',
      b:'Thêm mẫu tự chọn không sửa được thiên kiến.',
      c:'Đúng. Câu hỏi mở với mẫu người mua cho biết lý do thật phổ biến tới đâu.',
      d:'Lượt thích bài KOL đo sự chú ý tới KOL, không đo lý do mua.'} },
  { type:'calc', stem:'Khảo sát 240 người mua lại, 18 người nhắc tới bao bì. Tỉ lệ nhắc tới bao bì là bao nhiêu %?',
    unit:'%', ans:7.5, tol:0.05, wrong:[[13.3,'SAI_MAU_SO'],[1333.3,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Tỉ lệ = người nhắc ÷ tổng người được hỏi.','18 ÷ 240 = 0,075 = <b>7,5%</b>.'] },
  { type:'mcq', stem:'Câu nào là dấu hiệu rõ nhất của thiên kiến xác nhận?',
    options:[{k:'a',t:'"Số liệu tháng này xấu nhưng chắc do ngày lễ, bình thường chiến dịch vẫn ổn"'},{k:'b',t:'"Trước khi chạy, mình ghi ra ngưỡng nào là thất bại"'},
             {k:'c',t:'"Mình hỏi thêm cả khách đã bỏ mua để nghe lý do"'},{k:'d',t:'"Kết quả trái với dự đoán ban đầu, nên mình cần xem lại các giả định đã đặt ra"'}],
    answer:'a', why:{a:'Đúng. Số xấu thì tìm lý do để gạt đi, số tốt thì nhận — đó là thiên kiến xác nhận.',
      b:'Đây là cách chống thiên kiến.',
      c:'Chủ động tìm dữ liệu ngược chiều là cách chống thiên kiến.',
      d:'Chấp nhận kết quả trái dự đoán là thái độ đúng.'} },
  { type:'mcq', stem:'Một thương hiệu mỹ phẩm tin khách thích bao bì màu hồng. Dữ liệu cho thấy màu hồng và màu trắng bán ngang nhau. Trưởng nhóm nói "chắc do màu trắng được giảm giá". Nên làm gì?',
    options:[{k:'a',t:'Chấp nhận lời giải thích vì giảm giá đúng là có ảnh hưởng tới doanh số'},{k:'b',t:'Kiểm tra: màu trắng có thật được giảm giá khác không, trước khi chấp nhận lý do'},
             {k:'c',t:'Bỏ màu trắng, dồn toàn bộ sản xuất vào màu hồng như dự định ban đầu'},{k:'d',t:'Chạy thêm quảng cáo cho màu hồng để kết quả nghiêng về giả thuyết'}],
    answer:'b', why:{a:'Chấp nhận lý do mà không kiểm là để niềm tin tự bảo vệ mình.',
      b:'Đúng. Lời giải thích cũng là một giả thuyết; phải kiểm trước khi dùng.',
      c:'Hành động theo niềm tin khi dữ liệu không ủng hộ.',
      d:'Tác động vào kết quả để nó khớp niềm tin là tự lừa.'} },
  { type:'mcq', stem:'Cách nào giúp một nhóm giảm thiên kiến xác nhận khi đọc kết quả?',
    options:[{k:'a',t:'Để người đưa ra ý tưởng tự đọc và trình bày kết quả của mình'},{k:'b',t:'Chỉ báo cáo kết quả khi đã chắc chắn giả thuyết là đúng'},
             {k:'c',t:'Giao một người đóng vai phản biện, tìm lý do giả thuyết sai'},{k:'d',t:'Dùng thật nhiều chỉ số để chắc có số ủng hộ giả thuyết'}],
    answer:'c', why:{a:'Người đưa ra ý tưởng là người dễ thiên kiến nhất.',
      b:'Báo cáo có chọn lọc làm thiên kiến nặng hơn.',
      c:'Đúng. Có người được giao nhiệm vụ tìm bằng chứng ngược chiều giúp cân bằng.',
      d:'Càng nhiều chỉ số càng dễ nhặt số mình thích.'} },
  { type:'mcq', stem:'Vì sao ngưỡng đặt trước giúp chống thiên kiến xác nhận?',
    options:[{k:'a',t:'Vì ngưỡng làm kết quả dễ đạt hơn nên ít người trong nhóm phải bào chữa cho số xấu'},{k:'b',t:'Vì có ngưỡng thì không cần xem dữ liệu chi tiết nữa'},
             {k:'c',t:'Vì sếp sẽ kiểm tra ngưỡng thay cho nhóm thực hiện'},{k:'d',t:'Vì quyết định sai hay đúng được chốt trước khi thấy số, khó bẻ theo ý mình'}],
    answer:'d', why:{a:'Ngưỡng không làm kết quả dễ đạt hơn; nó làm kết quả khó bị diễn giải lại.',
      b:'Vẫn cần xem chi tiết để hiểu vì sao; ngưỡng chỉ chốt kết luận chính.',
      c:'Ngưỡng có tác dụng vì được chốt trước, không phụ thuộc ai kiểm.',
      d:'Đúng. Khi vạch đã có trước, khó dời vạch cho vừa niềm tin.'} }
  ] },

/* ------------------------------------------------------------------ 07 */
{ id:'B:gt03-07', skill:'channel', read:'6 phút', t:'Có ba giả thuyết mà tiền chỉ đủ kiểm một — chọn cái nào?',
  situation:'Một startup giao rau sạch ở Hà Nội có 3 giả thuyết để tăng đăng ký: gói theo tuần, giao buổi tối, và rau hữu cơ có chứng nhận. Mở dịch vụ giao tối thật tốn khoảng 30 triệu đồng thuê thêm người. Nhóm có 5 triệu đồng và 2 tuần để thử trước khi họp nhà đầu tư.',
  concept:{ name:'Kiểm rẻ nhất trước (thử nghiệm tối thiểu)',
    body:'Mỗi giả thuyết có thể kiểm bằng cách <b>rẻ hơn nhiều</b> so với làm thật. Thay vì mở dịch vụ, làm một trang đăng ký có nút "Giao buổi tối" và đếm bao nhiêu người bấm; thay vì nhập rau hữu cơ, hỏi đặt trước có cọc. Thứ tự nên chọn: giả thuyết nào vừa quan trọng nếu đúng, vừa không chắc, và rẻ nhất để có tín hiệu. Mục đích không phải chứng minh chắc chắn, mà là loại bớt ý tưởng trước khi tiêu tiền lớn.' },
  example:'Nhóm dựng trang đăng ký với ba lựa chọn, chạy 3 triệu đồng quảng cáo được 1.500 lượt vào. Giả thuyết: "Nếu có tuỳ chọn giao buổi tối, thì ít nhất 2% người vào sẽ để lại số điện thoại đăng ký, vì dân văn phòng không nhận hàng ban ngày." Kết quả: 30 người chọn giao tối, đúng 2%. Chi phí kiểm 3 triệu, bằng 10% chi phí làm thật — và giờ có tín hiệu để quyết định có bỏ 30 triệu hay không.',
  takeaway:'Tìm cách rẻ nhất để có tín hiệu, trước khi bỏ tiền làm thật.',
  apply:'Chọn một ý tưởng tốn tiền bạn từng nghe. Trong 60 giây, nói một cách kiểm nó dưới 1/10 chi phí làm thật.',
  mistakes:['Làm thật toàn bộ để "kiểm", tốn tiền trước khi biết có ai cần.','Chọn giả thuyết dễ kiểm nhưng không quan trọng, chỉ để có kết quả nhanh.'],
  q:[
  { type:'mcq', stem:'Với 5 triệu đồng và 2 tuần, cách tiếp cận nào khôn ngoan nhất?',
    options:[{k:'a',t:'Dồn tiền mở thử giao tối ở một quận trong hai tuần để có số thật'},{k:'b',t:'Kiểm cả ba giả thuyết bằng cách rẻ trước, rồi mới làm thật cái thắng'},
             {k:'c',t:'Chọn giả thuyết mà nhóm tin nhất và làm thật luôn cho kịp họp'},{k:'d',t:'Hỏi nhà đầu tư nên chọn giả thuyết nào trước khi làm bất cứ gì'}],
    answer:'b', why:{a:'5 triệu không đủ làm thật đàng hoàng; kết quả sẽ bị méo vì dịch vụ chắp vá.',
      b:'Đúng. Kiểm rẻ nhiều giả thuyết cho tín hiệu để chọn đúng chỗ đặt tiền lớn.',
      c:'Tin nhất chưa chắc đúng; làm thật luôn là đặt cược toàn bộ.',
      d:'Nhà đầu tư cần dữ liệu từ bạn, không phải ngược lại.'} },
  { type:'mcq', stem:'Bạn phải chọn cách kiểm giả thuyết "khách cần giao buổi tối". Bạn chọn cách nào?',
    options:[{k:'a',t:'Thuê hai shipper ca tối trong một tháng và đếm số đơn thực tế giao được'},{k:'b',t:'Hỏi 10 người bạn xem họ có thích được giao rau buổi tối hay không'},
             {k:'c',t:'Xem đối thủ có giao tối không, nếu có thì mình cũng làm theo'},{k:'d',t:'Thêm tuỳ chọn "giao tối" trên trang đăng ký, đếm người chọn và để lại số'}],
    answer:'d', why:{a:'Đây là làm thật, tốn gấp nhiều lần so với cần để có tín hiệu.',
      b:'Bạn bè không phải khách, và "thích" chưa phải hành động.',
      c:'Đối thủ làm không chứng minh khách của bạn cần.',
      d:'Đúng. Rẻ, nhanh, và đo hành vi thật (để lại số) thay vì lời nói.'} },
  { type:'calc', stem:'Trang đăng ký có 1.500 lượt vào, 2% chọn giao tối và để lại số. Có bao nhiêu người đăng ký giao tối?',
    unit:'người', ans:30, tol:0.1, wrong:[[300,'NHAM_DIEM_PHAN_TRAM'],[3000,'SAI_TINH_TOAN']], errors:['NHAM_DIEM_PHAN_TRAM'],
    steps:['Số người = lượt vào × tỉ lệ.','1.500 × 2% = 1.500 × 0,02 = <b>30 người</b>.'] },
  { type:'mcq', stem:'Trong ba giả thuyết, cái nào nên được ưu tiên kiểm trước?',
    options:[{k:'a',t:'Cái quan trọng nếu đúng, còn rất không chắc, và rẻ để có tín hiệu'},{k:'b',t:'Cái cả nhóm tin chắc nhất, để có kết quả tốt báo cáo nhà đầu tư'},
             {k:'c',t:'Cái đắt nhất khi làm thật, vì cần chắc chắn trước khi bỏ tiền lớn'},{k:'d',t:'Cái dễ nhất để làm, bất kể kết quả có ảnh hưởng quyết định lớn hay không'}],
    answer:'a', why:{a:'Đúng. Cân cả ba: giá trị của việc biết, mức không chắc, và chi phí kiểm.',
      b:'Kiểm cái đã tin chắc thì học được ít nhất.',
      c:'Đắt khi làm thật là một yếu tố, nhưng phải cân với việc có kiểm rẻ được không.',
      d:'Dễ mà không ảnh hưởng quyết định thì kiểm cũng không đổi được gì.'} },
  { type:'mcq', stem:'Một tiệm bánh muốn mở chi nhánh 2 ở quận 7 với giả thuyết "quận 7 có nhu cầu bánh mì Pháp". Cách kiểm rẻ nhất có tín hiệu thật là?',
    options:[{k:'a',t:'Thuê mặt bằng 6 tháng thử, nếu lỗ thì đóng cửa rút lui'},{k:'b',t:'Đọc báo cáo dân số quận 7 và đếm số chung cư mới xây'},
             {k:'c',t:'Bán thử ở một quầy tạm cuối tuần, đếm số bán và khách hỏi mua lại'},{k:'d',t:'Đăng bài hỏi trên nhóm cư dân quận 7 xem có ai thích ăn bánh mì Pháp'}],
    answer:'c', why:{a:'Đây là làm thật, tốn rất nhiều trước khi biết.',
      b:'Số dân không cho biết họ có mua bánh mì Pháp của bạn không.',
      c:'Đúng. Rẻ, nhanh và đo hành vi mua thật tại đúng khu vực.',
      d:'"Thích" trên mạng không phải mua; người trả lời cũng là mẫu tự chọn.'} },
  { type:'mcq', stem:'Kiểm rẻ cho ra 2% đăng ký giao tối. Điều gì KHÔNG nên kết luận ngay?',
    options:[{k:'a',t:'Có một nhóm khách quan tâm tới giao buổi tối đủ để xem xét tiếp'},{k:'b',t:'Chắc chắn 2% khách thật sẽ mua đều đặn khi mở dịch vụ giao tối'},
             {k:'c',t:'Giao tối đáng được đưa vào danh sách giả thuyết để kiểm bước sâu hơn'},{k:'d',t:'Tín hiệu này đủ để so sánh với hai giả thuyết còn lại ở cùng cách đo'}],
    answer:'b', why:{a:'Kết luận hợp lý từ tín hiệu có được.',
      b:'Đúng. Để lại số khác với mua đều đặn; kiểm rẻ cho tín hiệu, không cho chắc chắn.',
      c:'Đây chính là cách dùng kết quả kiểm rẻ.',
      d:'Cùng cách đo thì so được với nhau.'} },
  { type:'mcq', stem:'Vì sao chi phí kiểm 3 triệu so với chi phí làm thật 30 triệu là một lựa chọn tốt?',
    options:[{k:'a',t:'Vì 3 triệu chắc chắn cho ra kết quả chính xác như khi làm thật'},{k:'b',t:'Vì nhà đầu tư luôn thích thấy nhóm tiêu ít tiền ở giai đoạn đầu'},
             {k:'c',t:'Vì kết quả kiểm rẻ luôn tốt hơn kết quả kiểm đắt'},{k:'d',t:'Vì nếu giả thuyết sai, bạn mất 3 triệu thay vì 30 triệu'}],
    answer:'d', why:{a:'Kiểm rẻ kém chính xác hơn; đổi lại là rủi ro thấp.',
      b:'Lý do chính là giới hạn thua lỗ, không phải làm vừa lòng nhà đầu tư.',
      c:'Không có chuyện "luôn tốt hơn"; kiểm rẻ chỉ cho tín hiệu sớm.',
      d:'Đúng. Kiểm rẻ giới hạn thiệt hại khi sai, và đa số giả thuyết mới sẽ sai.'} }
  ] },

/* ------------------------------------------------------------------ 08 */
{ id:'B:gt03-08', skill:'measure', read:'6 phút', t:'Giả thuyết sai rồi — tiền đã mất hay đã mua được bài học?',
  situation:'Một thương hiệu cà phê hoà tan thử tặng kèm ly sứ cho đơn từ 200.000 đồng trên Tiki, giả thuyết: "Tặng ly sẽ tăng giá trị đơn trung bình từ 160.000 lên 200.000 đồng vì khách muốn đủ điều kiện nhận quà." Chạy thử 2 tuần tốn 5 triệu đồng. Giá trị đơn chỉ lên 165.000 đồng. Sếp hỏi: "Có nên bỏ 80 triệu làm chương trình quà cả quý không?"',
  concept:{ name:'Học từ giả thuyết sai',
    body:'Một giả thuyết sai không phải thất bại nếu nó <b>chặn được một quyết định tốn kém</b> và <b>chỉ ra khâu nào lý luận bị hỏng</b>. Khi kết quả không đạt, hỏi ba câu: phần "thì" sai hay phần "vì" sai? Ta đã thực hiện đúng như kế hoạch chưa (lỗi làm, không phải lỗi ý)? Và điều này loại bỏ những hướng nào? Câu trả lời là giả thuyết mới, tốt hơn cái cũ.' },
  example:'Giá trị đơn chỉ tăng 5.000 đồng. Kiểm thực hiện: banner quà hiện đúng, khách thấy được. Kiểm phần "vì": khảo sát nhanh cho thấy khách mua cà phê hoà tan theo gói quen, ít muốn mua thêm để lấy quà. Bài học: quà không kéo đơn to lên với ngành hàng mua theo thói quen. Thử nghiệm 5 triệu chặn được khoản 80 triệu — chỉ bằng 6,25% chi phí làm thật. Giả thuyết mới: quà có thể giúp kéo khách mới thử lần đầu.',
  takeaway:'Giả thuyết sai mà rẻ và rõ là tiền mua bài học, không phải tiền mất.',
  apply:'Nhớ một lần bạn làm sai điều gì đó. Trong 60 giây, nói: phần kết quả sai hay phần lý do sai, và bài học tiếp theo là gì.',
  mistakes:['Vội bỏ cả hướng đi mà không hỏi lỗi nằm ở cách làm hay ở ý tưởng.','Giấu kết quả sai nên cả nhóm lặp lại cùng một thử nghiệm.'],
  q:[
  { type:'mcq', stem:'Giá trị đơn chỉ tăng 5.000 đồng. Bước đầu tiên nên là gì?',
    options:[{k:'a',t:'Kết luận ngay khuyến mãi quà tặng không bao giờ hiệu quả với cà phê'},{k:'b',t:'Tăng giá trị quà tặng lên để kết quả lần sau cao hơn'},
             {k:'c',t:'Kiểm xem chương trình được thực hiện đúng chưa, rồi xem lý do nào hỏng'},{k:'d',t:'Chạy thêm hai tuần nữa hy vọng khách quen dần với chương trình'}],
    answer:'c', why:{a:'Kết luận quá rộng từ một thử nghiệm; còn chưa tách lỗi làm và lỗi ý.',
      b:'Tăng quà mà chưa hiểu vì sao sai là thêm tiền vào cùng một lý luận hỏng.',
      c:'Đúng. Tách lỗi thực hiện và lỗi lý luận trước khi rút bài học.',
      d:'Kéo dài vì hy vọng là dời vạch sai.'} },
  { type:'mcq', stem:'Sếp hỏi có nên bỏ 80 triệu làm chương trình quà cả quý không. Bạn đề xuất gì?',
    options:[{k:'a',t:'Vẫn làm, nhưng giảm ngân sách xuống còn 40 triệu để giảm bớt rủi ro'},{k:'b',t:'Không làm cho mục tiêu tăng giá trị đơn; đề xuất thử quà cho khách mới'},
             {k:'c',t:'Làm đủ 80 triệu, vì quy mô lớn hơn có thể cho kết quả khác'},{k:'d',t:'Tạm dừng mọi khuyến mãi quà tặng cho tới hết năm để an toàn'}],
    answer:'b', why:{a:'Giảm một nửa một ý tưởng đã bị bác vẫn là tiêu tiền vào nó.',
      b:'Đúng. Dữ liệu bác giả thuyết cũ; bài học mở ra giả thuyết mới đáng thử rẻ.',
      c:'Không có lý do để tin quy mô lớn đổi được hành vi mua theo thói quen.',
      d:'Bỏ hết là rút bài học quá rộng; quà vẫn có thể có tác dụng ở mục tiêu khác.'} },
  { type:'calc', stem:'Thử nghiệm tốn 5 triệu đồng, chương trình thật dự kiến 80 triệu đồng. Chi phí thử bằng bao nhiêu % chi phí làm thật?',
    unit:'%', ans:6.25, tol:0.05, wrong:[[1600,'SAI_MAU_SO'],[16,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Tỉ lệ = chi phí thử ÷ chi phí làm thật.','5 ÷ 80 = 0,0625 = <b>6,25%</b>.'] },
  { type:'mcq', stem:'Banner quà chỉ hiện trên máy tính, không hiện trên app điện thoại nơi 80% khách mua. Điều này nói gì về kết quả?',
    options:[{k:'a',t:'Giả thuyết đã sai rõ ràng, không cần kiểm lại nữa'},{k:'b',t:'Kết quả vẫn dùng được vì 20% khách vẫn thấy banner'},
             {k:'c',t:'Đây là bằng chứng quà tặng không có tác dụng với khách mobile'},{k:'d',t:'Đây là lỗi thực hiện; chưa kiểm được ý tưởng, cần làm lại'}],
    answer:'d', why:{a:'Phần lớn khách không thấy quà, nên chưa thể nói ý tưởng sai.',
      b:'20% thấy không đủ để đọc kết quả chung như một lần kiểm thật.',
      c:'Khách mobile không thấy quà nên không thể nói gì về tác dụng với họ.',
      d:'Đúng. Khi thực hiện hỏng, kết quả không nói gì về giả thuyết.'} },
  { type:'mcq', stem:'Vì sao nên ghi lại và chia sẻ cả những giả thuyết sai?',
    options:[{k:'a',t:'Để người khác trong công ty không lặp lại cùng một thử nghiệm tốn tiền'},{k:'b',t:'Để chứng minh với sếp là nhóm đã làm việc chăm chỉ trong quý'},
             {k:'c',t:'Để có tài liệu đổ lỗi cho người đưa ra ý tưởng ban đầu'},{k:'d',t:'Để đủ số lượng báo cáo theo quy định của phòng marketing'}],
    answer:'a', why:{a:'Đúng. Kết quả sai là tài sản của cả tổ chức nếu được ghi lại.',
      b:'Mục đích là học, không phải chứng minh chăm chỉ.',
      c:'Dùng để đổ lỗi sẽ khiến người ta giấu kết quả sai.',
      d:'Ghi cho đủ số thì mất tác dụng học.'} },
  { type:'mcq', stem:'Một chuỗi trà chanh thử mở bán lúc 6 giờ sáng, giả thuyết "sinh viên mua trước giờ học". Doanh số sáng rất thấp. Bài học hữu ích nhất?',
    options:[{k:'a',t:'Sinh viên không thích trà chanh nên chuỗi cần đổi sản phẩm chủ lực'},{k:'b',t:'Mở sáng chưa kéo sinh viên — kiểm tiếp xem họ mua lúc nào'},
             {k:'c',t:'Buổi sáng là khung giờ kém với mọi đồ uống nên không nên thử lại'},{k:'d',t:'Cần giảm giá mạnh vào buổi sáng để kéo sinh viên tới quán'}],
    answer:'b', why:{a:'Kết luận vượt quá dữ liệu; thử nghiệm chỉ nói về khung giờ.',
      b:'Đúng. Bài học vừa phạm vi, và dẫn tới giả thuyết tiếp theo.',
      c:'Quá rộng; cà phê sáng vẫn bán tốt ở nhiều nơi.',
      d:'Nhảy sang giải pháp mà chưa hiểu vì sao buổi sáng không có khách.'} },
  { type:'mcq', stem:'Câu nào mô tả đúng giá trị của một giả thuyết sai được kiểm rẻ?',
    options:[{k:'a',t:'Nó chỉ có giá trị khi được kiểm lại và cho ra kết quả đúng'},{k:'b',t:'Nó cho thấy nhóm đã chọn sai người phụ trách ngay từ đầu'},
             {k:'c',t:'Nó chặn một khoản chi lớn và thu hẹp các hướng còn lại'},{k:'d',t:'Nó không có giá trị vì không mang lại doanh thu trực tiếp'}],
    answer:'c', why:{a:'Giá trị đã có ngay ở lần sai, không cần đợi đúng.',
      b:'Giả thuyết sai là bình thường, không phải lỗi của người phụ trách.',
      c:'Đúng. Tránh chi sai và thu hẹp hướng đi là hai giá trị chính.',
      d:'Tránh mất 80 triệu cũng là giá trị kinh doanh.'} }
  ] },

/* ------------------------------------------------------------------ 09 */
{ id:'B:gt03-09', skill:'measure', read:'6 phút', t:'Vì sao nhóm cứ thử lại những ý đã thử năm ngoái?',
  situation:'Một chuỗi mỹ phẩm ở TP.HCM có nhóm marketing mới. Họ đề xuất "tặng mẫu thử kèm đơn online để tăng mua lại". Một nhân viên cũ nhớ mang máng năm ngoái đã thử, nhưng không ai tìm được kết quả. Trong năm, nhóm đã thử 12 ý tưởng, nhưng chỉ nhớ rõ 3 cái thắng.',
  concept:{ name:'Nhật ký giả thuyết',
    body:'Nhật ký giả thuyết là một bảng đơn giản, mỗi dòng một thử nghiệm: <b>ngày, giả thuyết Nếu–thì–vì, chỉ số và ngưỡng, kết quả, kết luận, bài học, bước tiếp</b>. Điền phần đầu trước khi chạy, phần sau khi có số. Nó giúp ba việc: không lặp lại thử nghiệm cũ, thấy được tỉ lệ thắng thật của nhóm, và biết mình hay sai ở loại giả thuyết nào. Một bảng tính chia sẻ là đủ; điều quan trọng là thói quen ghi cả cái thua.' },
  example:'Nhóm dựng bảng và ghi lại 12 thử nghiệm của năm từ email và báo cáo cũ. Kết quả: 3 thắng, 7 thua, 2 không kết luận được vì thực hiện hỏng. Tỉ lệ thắng 25%. Dòng tháng 5 năm ngoái: tặng mẫu thử — mua lại tăng 1 điểm, dưới ngưỡng 3 điểm, bài học "mẫu thử hợp kéo khách mới hơn là giữ khách cũ". Nhóm bỏ đề xuất cũ, tiết kiệm một vòng thử.',
  takeaway:'Ghi mọi giả thuyết, cả cái thua, vào một bảng chung — trí nhớ của nhóm không đáng tin.',
  apply:'Trong 60 giây, nói các cột bạn sẽ đặt cho một nhật ký giả thuyết và cột nào phải điền trước khi chạy.',
  mistakes:['Chỉ ghi thử nghiệm thắng, nên tỉ lệ thắng trông cao giả tạo.','Điền giả thuyết và ngưỡng sau khi đã có kết quả.'],
  q:[
  { type:'mcq', stem:'Vì sao nhóm chỉ nhớ rõ 3 thử nghiệm thắng trong 12?',
    options:[{k:'a',t:'Vì các thử nghiệm thua thường không đáng nhớ và không có giá trị'},{k:'b',t:'Vì người ta hay kể và lưu cái thắng; cái thua không ai ghi lại'},
             {k:'c',t:'Vì nhân viên cũ nghỉ việc nên mất hết thông tin'},{k:'d',t:'Vì 12 thử nghiệm một năm là quá nhiều để theo dõi'}],
    answer:'b', why:{a:'Cái thua có giá trị ngang cái thắng, nhất là để tránh lặp lại.',
      b:'Đúng. Không có nơi ghi chung, trí nhớ nhóm giữ lại chuyện thắng.',
      c:'Nghỉ việc làm mất thêm, nhưng gốc là không có ghi chép.',
      d:'12 thử nghiệm dễ theo dõi nếu có một bảng.'} },
  { type:'mcq', stem:'Bạn được giao dựng nhật ký giả thuyết. Bạn chọn quy tắc nào quan trọng nhất?',
    options:[{k:'a',t:'Chỉ ghi các thử nghiệm có ngân sách lớn hơn 10 triệu đồng cho gọn'},{k:'b',t:'Ghi kết quả chi tiết bằng biểu đồ đẹp để tiện trình bày với sếp'},
             {k:'c',t:'Điền giả thuyết, chỉ số, ngưỡng trước khi chạy; ghi cả thử nghiệm thua'},{k:'d',t:'Để mỗi người tự giữ nhật ký riêng cho linh hoạt với cách làm'}],
    answer:'c', why:{a:'Thử nghiệm nhỏ cũng có bài học; bỏ đi làm bảng thiếu.',
      b:'Trình bày đẹp không quan trọng bằng ghi trước và ghi đủ.',
      c:'Đúng. Ghi trước chống sửa ngưỡng sau; ghi cả thua mới có tỉ lệ thắng thật.',
      d:'Nhật ký riêng thì không ai tìm được — đúng vấn đề đang gặp.'} },
  { type:'calc', stem:'Trong 12 thử nghiệm, có 3 thắng. Tỉ lệ thắng của nhóm là bao nhiêu %?',
    unit:'%', ans:25, tol:0.1, wrong:[[400,'SAI_MAU_SO'],[33.3,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Tỉ lệ thắng = số thắng ÷ tổng số thử nghiệm.','3 ÷ 12 = 0,25 = <b>25%</b>.'] },
  { type:'mcq', stem:'Tỉ lệ thắng 25% nên được hiểu thế nào?',
    options:[{k:'a',t:'Nhóm làm việc kém, cần thay đổi cách đưa ra ý tưởng ngay'},{k:'b',t:'Chỉ nên chạy những thử nghiệm chắc chắn thắng để tăng tỉ lệ'},
             {k:'c',t:'Tỉ lệ này quá thấp, cần ngừng thử nghiệm và quay về làm theo kinh nghiệm'},{k:'d',t:'Bình thường: đa số giả thuyết mới sẽ sai; quan trọng là kiểm rẻ và học'}],
    answer:'d', why:{a:'Tỉ lệ thắng thấp là đặc điểm của việc thử cái mới, không phải dấu hiệu kém.',
      b:'Chỉ chạy cái chắc thắng thì không học được gì mới.',
      c:'Không thử nghiệm thì 75% ý tưởng sai sẽ được làm thật với chi phí lớn.',
      d:'Đúng. Tỉ lệ thắng thật cho biết cần kiểm rẻ nhiều ý, không cược lớn vào một ý.'} },
  { type:'mcq', stem:'Cột nào trong nhật ký giúp ích nhiều nhất cho nhóm mới đọc lại sau một năm?',
    options:[{k:'a',t:'Cột bài học: kết quả nói gì và hướng nào đã được loại bỏ'},{k:'b',t:'Cột tên người đề xuất để biết ai giỏi đưa ra ý tưởng'},
             {k:'c',t:'Cột ngân sách để biết thử nghiệm nào tiêu nhiều tiền nhất'},{k:'d',t:'Cột ngày chạy để biết mùa nào nhóm làm nhiều việc nhất'}],
    answer:'a', why:{a:'Đúng. Bài học là thứ chuyển được sang người khác và dùng được ngay.',
      b:'Ghi người đề xuất có thể có, nhưng dễ biến bảng thành bảng thành tích.',
      c:'Ngân sách có ích nhưng không cho biết nên làm gì tiếp.',
      d:'Ngày hữu ích để xem mùa vụ, nhưng không phải cột quan trọng nhất.'} },
  { type:'mcq', stem:'Nhìn nhật ký, nhóm thấy 5 trong 7 thử nghiệm thua đều là giả thuyết về khuyến mãi quà tặng. Nên rút ra gì?',
    options:[{k:'a',t:'Không làm khuyến mãi quà tặng thêm lần nào nữa trong mọi trường hợp'},{k:'b',t:'Đó là trùng hợp, mỗi thử nghiệm độc lập nên không nói lên điều gì'},
             {k:'c',t:'Có thể nhóm đang đánh giá quá cao tác dụng của quà — cần xem lại giả định chung'},{k:'d',t:'Cần tăng giá trị quà tặng lên gấp đôi để các thử nghiệm sau thắng'}],
    answer:'c', why:{a:'Kết luận tuyệt đối quá mức từ dữ liệu.',
      b:'Một khuôn mẫu lặp lại là thông tin, không chỉ là trùng hợp.',
      c:'Đúng. Nhật ký cho thấy nhóm hay sai ở đâu — đó là bài học cấp cao hơn từng thử nghiệm.',
      d:'Tăng quà là tiếp tục cùng giả định đang sai lặp lại.'} },
  { type:'mcq', stem:'Một quản lý muốn điền cột ngưỡng SAU khi có kết quả "cho chính xác hơn". Vì sao đây là vấn đề?',
    options:[{k:'a',t:'Vì kết quả chưa được phòng tài chính kiểm tra và xác nhận lại'},{k:'b',t:'Vì bảng tính sẽ bị lệch định dạng khi sửa cột đã có'},
             {k:'c',t:'Vì cột ngưỡng cần được sếp phê duyệt trước khi điền'},{k:'d',t:'Vì ngưỡng điền sau sẽ bị kéo theo kết quả, làm mất tác dụng'}],
    answer:'d', why:{a:'Kiểm tra tài chính không liên quan tới thời điểm đặt ngưỡng.',
      b:'Định dạng là chuyện nhỏ, không phải vấn đề chính.',
      c:'Phê duyệt không giải quyết được việc ngưỡng bị chỉnh theo kết quả.',
      d:'Đúng. Ngưỡng đặt sau luôn có xu hướng vừa với kết quả đã thấy.'} }
  ] },

/* ------------------------------------------------------------------ 10 */
{ id:'B:gt03-10', skill:'comm', read:'7 phút', t:'Trong một case thi, giả thuyết nên xuất hiện ở đâu?',
  situation:'Một đội sinh viên thi case marketing cho một thương hiệu nước ép đóng chai. Đề cho: trang bán hàng có 50.000 lượt vào mỗi tháng, chuyển đổi 3%, giá trị đơn 150.000 đồng. Bài của đội có 25 slide ý tưởng sáng tạo nhưng không có một câu giả thuyết nào. Giám khảo hỏi: "Vì sao các bạn tin ý tưởng này sẽ hiệu quả?" — cả đội im lặng.',
  concept:{ name:'Giả thuyết là xương sống của bài case',
    body:'Trong bài case, giả thuyết nối <b>phân tích</b> với <b>giải pháp</b>. Sau phần chẩn đoán, nêu 1–2 giả thuyết chính theo khuôn Nếu–thì–vì, có số từ đề bài. Sau đó mỗi ý tưởng phải trỏ về một giả thuyết, và phần đo lường nói rõ chỉ số, ngưỡng và cách kiểm rẻ trước khi làm lớn. Giám khảo không cần bạn đúng chắc chắn; họ cần thấy bạn biết mình đang cược vào điều gì và sẽ biết sai bằng cách nào.' },
  example:'Đội viết lại: "Nếu thêm gói 3 chai theo tuần cho dân văn phòng, thì chuyển đổi tăng từ 3% lên 5% trong 2 tháng, vì khách hiện mua lẻ không nhớ đặt lại." Tính từ đề: 2 điểm × 50.000 lượt = 1.000 đơn thêm; 1.000 × 150.000 đồng = 150 triệu đồng doanh thu thêm mỗi tháng. Kiểm trước: chạy trang gói tuần 2 tuần với 10% lượt vào. Mọi slide sáng tạo sau đó đều phục vụ giả thuyết này.',
  takeaway:'Trong case, nói rõ bạn đang cược vào điều gì, bằng số nào, và sẽ biết sai ra sao.',
  apply:'Lấy một đề case bạn từng đọc. Trong 60 giây, nói một giả thuyết chính theo khuôn Nếu–thì–vì, có số từ đề.',
  mistakes:['Trình bày nhiều ý tưởng hay mà không nối về giả thuyết nào.','Đưa số mục tiêu to mà không tính lại được từ dữ liệu đề cho.'],
  q:[
  { type:'mcq', stem:'Giám khảo hỏi "Vì sao tin ý tưởng này hiệu quả?" thật ra đang muốn nghe gì?',
    options:[{k:'a',t:'Một ví dụ thương hiệu nổi tiếng từng làm ý tưởng tương tự và thành công'},{k:'b',t:'Cam kết của đội rằng ý tưởng chắc chắn thành công'},
             {k:'c',t:'Cơ chế vì sao ý tưởng tác động tới con số, và cách biết nếu sai'},{k:'d',t:'Số lượng ý tưởng dự phòng nếu ý tưởng chính không hiệu quả'}],
    answer:'c', why:{a:'Ví dụ giúp minh hoạ, nhưng không thay được lập luận cho chính case này.',
      b:'Cam kết chắc chắn không thuyết phục; giám khảo muốn thấy lý luận.',
      c:'Đúng. Đó chính là phần "vì" và ngưỡng sai của một giả thuyết.',
      d:'Nhiều ý dự phòng không trả lời câu "vì sao".'} },
  { type:'mcq', stem:'Còn một ngày trước vòng chung kết. Bạn sửa gì trong bài của đội?',
    options:[{k:'a',t:'Thêm 10 slide ý tưởng sáng tạo nữa để bài trông đầy đặn hơn'},{k:'b',t:'Thay toàn bộ hình ảnh cho đẹp và đồng bộ màu thương hiệu'},
             {k:'c',t:'Thêm một slide số liệu thị trường ngành nước ép từ nhiều nguồn'},{k:'d',t:'Thêm slide giả thuyết Nếu–thì–vì có số, và nối mỗi ý tưởng về đó'}],
    answer:'d', why:{a:'Thêm ý tưởng không có giả thuyết càng làm bài rời rạc.',
      b:'Hình ảnh đẹp không trả lời câu hỏi giám khảo đã hỏi.',
      c:'Số liệu thị trường không thay được việc nói rõ mình cược vào điều gì.',
      d:'Đúng. Đây là mảnh còn thiếu nối phân tích với giải pháp.'} },
  { type:'calc', stem:'50.000 lượt vào/tháng, chuyển đổi tăng từ 3% lên 5%, giá trị đơn 150.000 đồng. Doanh thu tăng thêm mỗi tháng là bao nhiêu triệu đồng?',
    unit:'triệu đồng', ans:150, tol:0.5, wrong:[[375,'SAI_TINH_TOAN'],[1500,'NHAM_DIEM_PHAN_TRAM']], errors:['NHAM_DIEM_PHAN_TRAM'],
    steps:['Đơn thêm = 50.000 × (5% − 3%) = 50.000 × 0,02 = 1.000 đơn.','Doanh thu thêm = 1.000 × 150.000 = 150.000.000 đồng = <b>150 triệu</b>.'] },
  { type:'mcq', stem:'Giả thuyết nên đặt ở vị trí nào trong bài case?',
    options:[{k:'a',t:'Ở slide cuối cùng như phần phụ lục cho giám khảo tham khảo thêm'},{k:'b',t:'Sau phần chẩn đoán, trước phần giải pháp — làm cầu nối giữa hai phần'},
             {k:'c',t:'Ở slide đầu tiên, trước cả khi phân tích tình hình thương hiệu'},{k:'d',t:'Không cần slide riêng, chỉ cần nói miệng khi được giám khảo hỏi'}],
    answer:'b', why:{a:'Để cuối thì giải pháp phía trước trông như không có căn cứ.',
      b:'Đúng. Giả thuyết rút từ chẩn đoán và dẫn tới giải pháp.',
      c:'Giả thuyết trước phân tích thì không có căn cứ.',
      d:'Chỉ nói khi bị hỏi là quá muộn; giám khảo chấm lập luận trên slide.'} },
  { type:'mcq', stem:'Một đội khác đặt mục tiêu "chuyển đổi tăng từ 3% lên 15%". Giám khảo có khả năng phản ứng thế nào?',
    options:[{k:'a',t:'Đánh giá cao vì mục tiêu tham vọng cho thấy đội tự tin và dám nghĩ lớn'},{k:'b',t:'Không quan tâm, vì mục tiêu con số chỉ là hình thức'},
             {k:'c',t:'Nghi ngờ, vì tăng gấp năm lần mà không có cơ chế thuyết phục là khó tin'},{k:'d',t:'Chấm điểm cao hơn vì con số lớn dễ gây ấn tượng'}],
    answer:'c', why:{a:'Tham vọng không có cơ chế cho thấy đội chưa hiểu bài toán.',
      b:'Giám khảo rất quan tâm con số có tính lại được không.',
      c:'Đúng. Ngưỡng phải hợp lý với cơ chế nêu ra; số quá lớn làm mất tin cậy.',
      d:'Ấn tượng ban đầu sẽ mất ngay khi bị hỏi "vì sao".'} },
  { type:'mcq', stem:'Trong phần đo lường của bài case, điều gì thể hiện tư duy giả thuyết tốt nhất?',
    options:[{k:'a',t:'Một kế hoạch thử nhỏ 2 tuần với ngưỡng đi tiếp hoặc dừng'},{k:'b',t:'Một danh sách dài KPI gồm lượt xem, lượt thích, chia sẻ và bình luận'},
             {k:'c',t:'Một biểu đồ dự báo doanh thu tăng đều mỗi tháng trong cả năm'},{k:'d',t:'Cam kết sẽ đo lường mọi thứ bằng công cụ phân tích hiện đại'}],
    answer:'a', why:{a:'Đúng. Thử nhỏ, có ngưỡng, có quyết định — đúng tinh thần kiểm chứng.',
      b:'Danh sách dài không cho biết số nào quyết định.',
      c:'Dự báo đẹp không nói gì về cách biết mình sai.',
      d:'Công cụ không thay được việc chọn chỉ số và ngưỡng.'} },
  { type:'mcq', stem:'Đề case cho biết khách mua lại thấp. Giả thuyết nào hợp nhất để đưa vào bài?',
    options:[{k:'a',t:'Nếu làm chương trình khách hàng thân thiết thì thương hiệu sẽ lớn mạnh hơn'},{k:'b',t:'Khách hàng hiện nay rất khó tính nên cần chăm sóc tốt hơn nữa'},
             {k:'c',t:'Nếu làm nhiều nội dung hay trên mạng xã hội thì khách sẽ yêu thương hiệu'},{k:'d',t:'Nếu nhắc qua Zalo sau 7 ngày thì mua lại tăng từ 10% lên 15%, vì khách quên đặt lại'}],
    answer:'d', why:{a:'"Lớn mạnh hơn" không đo được và không gắn với vấn đề mua lại.',
      b:'Đây là nhận định chung, không có hành động, số hay ngưỡng.',
      c:'"Yêu thương hiệu" không đo được và không gắn trực tiếp với mua lại.',
      d:'Đúng. Gắn đúng vấn đề đề bài, có hành động, số, ngưỡng và cơ chế.'} }
  ] }

]});
